CREATE TABLE IF NOT EXISTS "riders" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Optional: plenty of riders sign up with a phone number only, so this cannot be the identity column.
	"email" VARCHAR(320) UNIQUE,
	-- Verified number and the real login identity. Also how a driver reaches the rider at pickup, through a masked relay.
	"phone" VARCHAR(32) NOT NULL UNIQUE,
	-- Name shown to the driver on the offer card.
	"full_name" VARCHAR(160) NOT NULL,
	-- Opaque token from the payments processor. Card details never live here.
	"default_payment_method_ref" VARCHAR(120),
	-- Cached mean of the ratings drivers gave. Denormalised because dispatch reads it on every offer.
	"rating_avg" NUMERIC(3,2),
	-- Number of ratings behind rating_avg, so a single one-star does not define a new account.
	"rating_count" INTEGER NOT NULL DEFAULT 0,
	-- Signup time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "riders" IS 'The passenger side of the marketplace. Kept apart from drivers because the two go through completely different onboarding, compliance and payout paths even when the same person does both.';
COMMENT ON COLUMN "riders"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "riders"."email" IS 'Optional: plenty of riders sign up with a phone number only, so this cannot be the identity column.';
COMMENT ON COLUMN "riders"."phone" IS 'Verified number and the real login identity. Also how a driver reaches the rider at pickup, through a masked relay.';
COMMENT ON COLUMN "riders"."full_name" IS 'Name shown to the driver on the offer card.';
COMMENT ON COLUMN "riders"."default_payment_method_ref" IS 'Opaque token from the payments processor. Card details never live here.';
COMMENT ON COLUMN "riders"."rating_avg" IS 'Cached mean of the ratings drivers gave. Denormalised because dispatch reads it on every offer.';
COMMENT ON COLUMN "riders"."rating_count" IS 'Number of ratings behind rating_avg, so a single one-star does not define a new account.';
COMMENT ON COLUMN "riders"."created_at" IS 'Signup time.';

CREATE TABLE IF NOT EXISTS "drivers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Verified number and login identity.
	"phone" VARCHAR(32) NOT NULL UNIQUE,
	-- Legal name, which must match the licence on file.
	"full_name" VARCHAR(160) NOT NULL,
	-- Driving licence number. Unique within an issuing region, not globally.
	"licence_number" VARCHAR(64) NOT NULL,
	-- ISO 3166-1 alpha-2 code of the issuing country.
	"licence_country_code" CHAR(2) NOT NULL,
	-- pending | active | suspended | deactivated. Only active drivers can start a session.
	"status" VARCHAR(24) NOT NULL DEFAULT 'pending',
	-- Date of the last passed background check. Null blocks activation.
	"background_check_at" TIMESTAMPTZ,
	-- Cached mean of rider ratings, read on every dispatch decision.
	"rating_avg" NUMERIC(3,2),
	-- Sample size behind rating_avg.
	"rating_count" INTEGER NOT NULL DEFAULT 0,
	-- Opaque token for the payout account.
	"payout_account_ref" VARCHAR(120),
	-- City the driver is onboarded in, which determines the regulatory rules that apply.
	"home_city" VARCHAR(120),
	-- Onboarding start.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "drivers" IS 'The supply side. status is a compliance gate rather than a preference: it is flipped by expiring documents and by safety reports, and nothing about being online can override it.';
COMMENT ON COLUMN "drivers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "drivers"."phone" IS 'Verified number and login identity.';
COMMENT ON COLUMN "drivers"."full_name" IS 'Legal name, which must match the licence on file.';
COMMENT ON COLUMN "drivers"."licence_number" IS 'Driving licence number. Unique within an issuing region, not globally.';
COMMENT ON COLUMN "drivers"."licence_country_code" IS 'ISO 3166-1 alpha-2 code of the issuing country.';
COMMENT ON COLUMN "drivers"."status" IS 'pending | active | suspended | deactivated. Only active drivers can start a session.';
COMMENT ON COLUMN "drivers"."background_check_at" IS 'Date of the last passed background check. Null blocks activation.';
COMMENT ON COLUMN "drivers"."rating_avg" IS 'Cached mean of rider ratings, read on every dispatch decision.';
COMMENT ON COLUMN "drivers"."rating_count" IS 'Sample size behind rating_avg.';
COMMENT ON COLUMN "drivers"."payout_account_ref" IS 'Opaque token for the payout account.';
COMMENT ON COLUMN "drivers"."home_city" IS 'City the driver is onboarded in, which determines the regulatory rules that apply.';
COMMENT ON COLUMN "drivers"."created_at" IS 'Onboarding start.';

CREATE INDEX "idx_drivers_status"
ON "drivers" ("status");
CREATE UNIQUE INDEX "uq_drivers_licence"
ON "drivers" ("licence_country_code", "licence_number");

CREATE TABLE IF NOT EXISTS "vehicles" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Driver who registered it. One driver may keep several cars on file.
	"driver_id" BIGINT NOT NULL,
	-- Registration plate, shown to the rider so they get into the right car.
	"plate" VARCHAR(16) NOT NULL,
	-- Country the plate is registered in, needed because plates are only unique per country.
	"country_code" CHAR(2) NOT NULL,
	-- Manufacturer, shown on the rider pickup screen.
	"make" VARCHAR(60) NOT NULL,
	-- Model, shown alongside the plate.
	"model" VARCHAR(60) NOT NULL,
	-- Colour. Trivial data that does most of the work of finding the car at night.
	"colour" VARCHAR(32) NOT NULL,
	-- Model year. Many cities cap vehicle age by regulation.
	"year" SMALLINT,
	-- Passenger seats excluding the driver, which decides eligibility for larger product tiers.
	"seats" SMALLINT NOT NULL DEFAULT 4,
	-- standard | xl | comfort | premium | accessible. The tier a request can be matched to.
	"product_tier" VARCHAR(24) NOT NULL DEFAULT 'standard',
	-- False retires the car without deleting the trips it drove.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "vehicles" IS 'The car, not the driver. Trips reference both because insurance, tier eligibility and regulator reporting are all about which vehicle did the work, and the same driver may swap cars between sessions.';
COMMENT ON COLUMN "vehicles"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "vehicles"."driver_id" IS 'Driver who registered it. One driver may keep several cars on file.';
COMMENT ON COLUMN "vehicles"."plate" IS 'Registration plate, shown to the rider so they get into the right car.';
COMMENT ON COLUMN "vehicles"."country_code" IS 'Country the plate is registered in, needed because plates are only unique per country.';
COMMENT ON COLUMN "vehicles"."make" IS 'Manufacturer, shown on the rider pickup screen.';
COMMENT ON COLUMN "vehicles"."model" IS 'Model, shown alongside the plate.';
COMMENT ON COLUMN "vehicles"."colour" IS 'Colour. Trivial data that does most of the work of finding the car at night.';
COMMENT ON COLUMN "vehicles"."year" IS 'Model year. Many cities cap vehicle age by regulation.';
COMMENT ON COLUMN "vehicles"."seats" IS 'Passenger seats excluding the driver, which decides eligibility for larger product tiers.';
COMMENT ON COLUMN "vehicles"."product_tier" IS 'standard | xl | comfort | premium | accessible. The tier a request can be matched to.';
COMMENT ON COLUMN "vehicles"."is_active" IS 'False retires the car without deleting the trips it drove.';

CREATE UNIQUE INDEX "uq_vehicles_country_plate"
ON "vehicles" ("country_code", "plate");
CREATE INDEX "idx_vehicles_driver_active"
ON "vehicles" ("driver_id", "is_active");

CREATE TABLE IF NOT EXISTS "documents" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Driver the document belongs to, even when the subject is a vehicle, because the driver is who gets blocked.
	"driver_id" BIGINT NOT NULL,
	-- Vehicle the document covers. Null for personal documents such as the licence itself.
	"vehicle_id" BIGINT,
	-- drivers_licence | insurance | vehicle_registration | inspection | private_hire_permit | profile_photo.
	"kind" VARCHAR(32) NOT NULL,
	-- Storage key for the scanned file. The bytes live in object storage, never in the database.
	"document_ref" VARCHAR(200) NOT NULL,
	-- Issue date, printed on the document.
	"issued_on" DATE,
	-- Expiry date. Null only for documents that genuinely never expire.
	"expires_on" DATE,
	-- pending | approved | rejected | expired. Expired is set by a sweep, not by a human.
	"status" VARCHAR(24) NOT NULL DEFAULT 'pending',
	-- When a reviewer decided. Null while queued.
	"reviewed_at" TIMESTAMPTZ,
	-- Shown to the driver so a resubmission can actually fix the problem.
	"rejection_reason" VARCHAR(200),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "documents" IS 'Compliance paperwork with dates. The index on expires_on exists for one nightly job: find every document expiring tomorrow, warn the driver, and deactivate the ones that already lapsed. Storing expiry as a column on drivers cannot express five documents expiring on five different days.';
COMMENT ON COLUMN "documents"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "documents"."driver_id" IS 'Driver the document belongs to, even when the subject is a vehicle, because the driver is who gets blocked.';
COMMENT ON COLUMN "documents"."vehicle_id" IS 'Vehicle the document covers. Null for personal documents such as the licence itself.';
COMMENT ON COLUMN "documents"."kind" IS 'drivers_licence | insurance | vehicle_registration | inspection | private_hire_permit | profile_photo.';
COMMENT ON COLUMN "documents"."document_ref" IS 'Storage key for the scanned file. The bytes live in object storage, never in the database.';
COMMENT ON COLUMN "documents"."issued_on" IS 'Issue date, printed on the document.';
COMMENT ON COLUMN "documents"."expires_on" IS 'Expiry date. Null only for documents that genuinely never expire.';
COMMENT ON COLUMN "documents"."status" IS 'pending | approved | rejected | expired. Expired is set by a sweep, not by a human.';
COMMENT ON COLUMN "documents"."reviewed_at" IS 'When a reviewer decided. Null while queued.';
COMMENT ON COLUMN "documents"."rejection_reason" IS 'Shown to the driver so a resubmission can actually fix the problem.';

CREATE INDEX "idx_documents_driver_kind_status"
ON "documents" ("driver_id", "kind", "status");
CREATE INDEX "idx_documents_expiry_sweep"
ON "documents" ("expires_on");

CREATE TABLE IF NOT EXISTS "driver_sessions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Driver who went online.
	"driver_id" BIGINT NOT NULL,
	-- Car being driven this session. Fixed for the session, which is what makes insurance attribution unambiguous.
	"vehicle_id" BIGINT NOT NULL,
	-- Go-online time.
	"started_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Go-offline time. Null means the driver is online right now, which is the cheapest possible availability query.
	"ended_at" TIMESTAMPTZ,
	-- Where the session began, used for supply heat-mapping.
	"start_latitude" NUMERIC(9,6),
	-- Where the session began, used for supply heat-mapping.
	"start_longitude" NUMERIC(9,6),
	-- Operating city for the session, snapshotted because a driver can cross a city boundary mid-shift.
	"city" VARCHAR(120) NOT NULL,
	-- Running count, maintained so the driver earnings screen does not aggregate the trip table on every refresh.
	"trips_completed" INTEGER NOT NULL DEFAULT 0,
	-- Running driver earnings for the session in minor units.
	"earnings_minor" INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "driver_sessions" IS 'One row per shift. Legally mandated driving-hour limits, utilisation metrics and the question of who is even available to dispatch are all answered here rather than by a boolean on drivers.';
COMMENT ON COLUMN "driver_sessions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "driver_sessions"."driver_id" IS 'Driver who went online.';
COMMENT ON COLUMN "driver_sessions"."vehicle_id" IS 'Car being driven this session. Fixed for the session, which is what makes insurance attribution unambiguous.';
COMMENT ON COLUMN "driver_sessions"."started_at" IS 'Go-online time.';
COMMENT ON COLUMN "driver_sessions"."ended_at" IS 'Go-offline time. Null means the driver is online right now, which is the cheapest possible availability query.';
COMMENT ON COLUMN "driver_sessions"."start_latitude" IS 'Where the session began, used for supply heat-mapping.';
COMMENT ON COLUMN "driver_sessions"."start_longitude" IS 'Where the session began, used for supply heat-mapping.';
COMMENT ON COLUMN "driver_sessions"."city" IS 'Operating city for the session, snapshotted because a driver can cross a city boundary mid-shift.';
COMMENT ON COLUMN "driver_sessions"."trips_completed" IS 'Running count, maintained so the driver earnings screen does not aggregate the trip table on every refresh.';
COMMENT ON COLUMN "driver_sessions"."earnings_minor" IS 'Running driver earnings for the session in minor units.';

CREATE INDEX "idx_sessions_driver_started"
ON "driver_sessions" ("driver_id", "started_at");
CREATE INDEX "idx_sessions_online_by_city"
ON "driver_sessions" ("city", "ended_at");

CREATE TABLE IF NOT EXISTS "surge_zones" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- City the zone belongs to.
	"city" VARCHAR(120) NOT NULL,
	-- Short zone name, e.g. AIRPORT-T2 or DOWNTOWN-N.
	"code" VARCHAR(32) NOT NULL,
	-- Approximate centre, used to map a pickup point to a zone without a spatial extension.
	"centroid_latitude" NUMERIC(9,6) NOT NULL,
	-- Approximate centre, used to map a pickup point to a zone without a spatial extension.
	"centroid_longitude" NUMERIC(9,6) NOT NULL,
	-- Crude catchment radius. Real deployments use a hex grid or polygons; the shape of the table does not change.
	"radius_metres" INTEGER NOT NULL DEFAULT 1500,
	-- False retires a zone while keeping the multipliers it produced.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "surge_zones" IS 'The geographic unit pricing is computed over. Zones are coarse on purpose: surge has to be explainable to a driver looking at a map, and per-point pricing is neither explainable nor cacheable.';
COMMENT ON COLUMN "surge_zones"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "surge_zones"."city" IS 'City the zone belongs to.';
COMMENT ON COLUMN "surge_zones"."code" IS 'Short zone name, e.g. AIRPORT-T2 or DOWNTOWN-N.';
COMMENT ON COLUMN "surge_zones"."centroid_latitude" IS 'Approximate centre, used to map a pickup point to a zone without a spatial extension.';
COMMENT ON COLUMN "surge_zones"."centroid_longitude" IS 'Approximate centre, used to map a pickup point to a zone without a spatial extension.';
COMMENT ON COLUMN "surge_zones"."radius_metres" IS 'Crude catchment radius. Real deployments use a hex grid or polygons; the shape of the table does not change.';
COMMENT ON COLUMN "surge_zones"."is_active" IS 'False retires a zone while keeping the multipliers it produced.';

CREATE UNIQUE INDEX "uq_surge_zones_city_code"
ON "surge_zones" ("city", "code");

CREATE TABLE IF NOT EXISTS "surge_multipliers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Zone being priced.
	"zone_id" BIGINT NOT NULL,
	-- Tier the multiplier applies to. Premium supply runs out at a different rate than standard.
	"product_tier" VARCHAR(24) NOT NULL DEFAULT 'standard',
	-- Start of the pricing window, usually a few minutes long.
	"effective_from" TIMESTAMPTZ NOT NULL,
	-- End of the window. Closed rather than open-ended, so a pricing engine crash cannot leave 3x running all night.
	"effective_to" TIMESTAMPTZ NOT NULL,
	-- Factor applied to the base and distance components. 1.00 means no surge.
	"multiplier" NUMERIC(4,2) NOT NULL DEFAULT 1,
	-- Unmatched requests observed in the window, kept so a pricing decision can be audited after a complaint.
	"open_requests" INTEGER,
	-- Idle drivers observed in the window, the other half of the same audit.
	"available_drivers" INTEGER,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "surge_multipliers" IS 'Surge as a time series per zone and tier, not a live number. Every trip snapshots the multiplier it was quoted, and this table is what proves that quote was the rate in force at that minute.';
COMMENT ON COLUMN "surge_multipliers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "surge_multipliers"."zone_id" IS 'Zone being priced.';
COMMENT ON COLUMN "surge_multipliers"."product_tier" IS 'Tier the multiplier applies to. Premium supply runs out at a different rate than standard.';
COMMENT ON COLUMN "surge_multipliers"."effective_from" IS 'Start of the pricing window, usually a few minutes long.';
COMMENT ON COLUMN "surge_multipliers"."effective_to" IS 'End of the window. Closed rather than open-ended, so a pricing engine crash cannot leave 3x running all night.';
COMMENT ON COLUMN "surge_multipliers"."multiplier" IS 'Factor applied to the base and distance components. 1.00 means no surge.';
COMMENT ON COLUMN "surge_multipliers"."open_requests" IS 'Unmatched requests observed in the window, kept so a pricing decision can be audited after a complaint.';
COMMENT ON COLUMN "surge_multipliers"."available_drivers" IS 'Idle drivers observed in the window, the other half of the same audit.';

CREATE INDEX "idx_surge_zone_tier_from"
ON "surge_multipliers" ("zone_id", "product_tier", "effective_from");

CREATE TABLE IF NOT EXISTS "ride_requests" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Passenger asking for a car.
	"rider_id" BIGINT NOT NULL,
	-- Tier requested, which restricts the vehicles dispatch may offer to.
	"product_tier" VARCHAR(24) NOT NULL DEFAULT 'standard',
	-- Requested pickup point.
	"pickup_latitude" NUMERIC(9,6) NOT NULL,
	-- Requested pickup point.
	"pickup_longitude" NUMERIC(9,6) NOT NULL,
	-- Reverse-geocoded label, snapshotted because geocoders change their minds.
	"pickup_address" VARCHAR(240),
	-- Requested destination. Null is legal: some markets let riders hail without entering one.
	"dropoff_latitude" NUMERIC(9,6),
	-- Requested destination, null when the rider did not give one.
	"dropoff_longitude" NUMERIC(9,6),
	-- Reverse-geocoded destination label.
	"dropoff_address" VARCHAR(240),
	-- Zone the pickup fell into, resolved once at request time and reused for pricing and analytics.
	"pickup_zone_id" BIGINT,
	-- Multiplier shown to the rider before they confirmed. Binding even if surge moves while a car is found.
	"quoted_surge_multiplier" NUMERIC(4,2) NOT NULL DEFAULT 1,
	-- Upfront price quote in minor units, null in markets that meter instead.
	"quoted_fare_minor" INTEGER,
	-- Currency of the quote.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- searching | matched | no_drivers | cancelled | expired.
	"status" VARCHAR(24) NOT NULL DEFAULT 'searching',
	-- When the rider tapped confirm.
	"requested_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When a driver accepted. The gap from requested_at is the metric the whole dispatch system is tuned on.
	"matched_at" TIMESTAMPTZ,
	-- Cancellation time. Kept because pre-match cancellations mean something very different from post-match ones.
	"cancelled_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "ride_requests" IS 'The ask, which is not the trip. Most of the interesting failure modes — no cars, rider gave up, price rejected — happen to a request that never becomes a trip, and they all need somewhere to live.';
COMMENT ON COLUMN "ride_requests"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "ride_requests"."rider_id" IS 'Passenger asking for a car.';
COMMENT ON COLUMN "ride_requests"."product_tier" IS 'Tier requested, which restricts the vehicles dispatch may offer to.';
COMMENT ON COLUMN "ride_requests"."pickup_latitude" IS 'Requested pickup point.';
COMMENT ON COLUMN "ride_requests"."pickup_longitude" IS 'Requested pickup point.';
COMMENT ON COLUMN "ride_requests"."pickup_address" IS 'Reverse-geocoded label, snapshotted because geocoders change their minds.';
COMMENT ON COLUMN "ride_requests"."dropoff_latitude" IS 'Requested destination. Null is legal: some markets let riders hail without entering one.';
COMMENT ON COLUMN "ride_requests"."dropoff_longitude" IS 'Requested destination, null when the rider did not give one.';
COMMENT ON COLUMN "ride_requests"."dropoff_address" IS 'Reverse-geocoded destination label.';
COMMENT ON COLUMN "ride_requests"."pickup_zone_id" IS 'Zone the pickup fell into, resolved once at request time and reused for pricing and analytics.';
COMMENT ON COLUMN "ride_requests"."quoted_surge_multiplier" IS 'Multiplier shown to the rider before they confirmed. Binding even if surge moves while a car is found.';
COMMENT ON COLUMN "ride_requests"."quoted_fare_minor" IS 'Upfront price quote in minor units, null in markets that meter instead.';
COMMENT ON COLUMN "ride_requests"."currency_code" IS 'Currency of the quote.';
COMMENT ON COLUMN "ride_requests"."status" IS 'searching | matched | no_drivers | cancelled | expired.';
COMMENT ON COLUMN "ride_requests"."requested_at" IS 'When the rider tapped confirm.';
COMMENT ON COLUMN "ride_requests"."matched_at" IS 'When a driver accepted. The gap from requested_at is the metric the whole dispatch system is tuned on.';
COMMENT ON COLUMN "ride_requests"."cancelled_at" IS 'Cancellation time. Kept because pre-match cancellations mean something very different from post-match ones.';

CREATE INDEX "idx_requests_rider_time"
ON "ride_requests" ("rider_id", "requested_at");
CREATE INDEX "idx_requests_open"
ON "ride_requests" ("status", "requested_at");
CREATE INDEX "idx_requests_zone_time"
ON "ride_requests" ("pickup_zone_id", "requested_at");

CREATE TABLE IF NOT EXISTS "dispatch_offers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Request being offered out.
	"request_id" BIGINT NOT NULL,
	-- Driver the offer went to.
	"driver_id" BIGINT NOT NULL,
	-- Session the driver was online in. Null if the session ended before the offer resolved.
	"session_id" BIGINT,
	-- Position in the offer chain: 1 is the first driver asked, 2 the next after a decline. Acceptance rate by position is how dispatch is tuned.
	"sequence" SMALLINT NOT NULL,
	-- When the card appeared on the driver device.
	"offered_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Hard deadline, usually 10 to 15 seconds. Without it one unresponsive phone stalls a rider indefinitely.
	"expires_at" TIMESTAMPTZ NOT NULL,
	-- When the driver tapped. Null on timeout, which is exactly how a timeout is distinguished from a decline.
	"responded_at" TIMESTAMPTZ,
	-- offered | accepted | declined | timed_out | superseded.
	"status" VARCHAR(24) NOT NULL DEFAULT 'offered',
	-- Predicted seconds to pickup at offer time. Compared against reality later to score the ETA model.
	"eta_seconds" INTEGER,
	-- Straight-line or routed distance at offer time.
	"distance_to_pickup_metres" INTEGER,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "dispatch_offers" IS 'One row per driver asked, not one per match. Keeping declines and timeouts is the entire dataset behind acceptance rate, ETA accuracy and why a rider waited four minutes, and none of it survives if dispatch just writes the winner onto the request.';
COMMENT ON COLUMN "dispatch_offers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "dispatch_offers"."request_id" IS 'Request being offered out.';
COMMENT ON COLUMN "dispatch_offers"."driver_id" IS 'Driver the offer went to.';
COMMENT ON COLUMN "dispatch_offers"."session_id" IS 'Session the driver was online in. Null if the session ended before the offer resolved.';
COMMENT ON COLUMN "dispatch_offers"."sequence" IS 'Position in the offer chain: 1 is the first driver asked, 2 the next after a decline. Acceptance rate by position is how dispatch is tuned.';
COMMENT ON COLUMN "dispatch_offers"."offered_at" IS 'When the card appeared on the driver device.';
COMMENT ON COLUMN "dispatch_offers"."expires_at" IS 'Hard deadline, usually 10 to 15 seconds. Without it one unresponsive phone stalls a rider indefinitely.';
COMMENT ON COLUMN "dispatch_offers"."responded_at" IS 'When the driver tapped. Null on timeout, which is exactly how a timeout is distinguished from a decline.';
COMMENT ON COLUMN "dispatch_offers"."status" IS 'offered | accepted | declined | timed_out | superseded.';
COMMENT ON COLUMN "dispatch_offers"."eta_seconds" IS 'Predicted seconds to pickup at offer time. Compared against reality later to score the ETA model.';
COMMENT ON COLUMN "dispatch_offers"."distance_to_pickup_metres" IS 'Straight-line or routed distance at offer time.';

CREATE UNIQUE INDEX "uq_offers_request_sequence"
ON "dispatch_offers" ("request_id", "sequence");
CREATE INDEX "idx_offers_driver_time"
ON "dispatch_offers" ("driver_id", "offered_at");
CREATE INDEX "idx_offers_expiry_sweep"
ON "dispatch_offers" ("status", "expires_at");

CREATE TABLE IF NOT EXISTS "trips" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Originating request. Unique, so one request can never spawn two trips.
	"request_id" BIGINT NOT NULL UNIQUE,
	-- Passenger, copied from the request so the trip stands alone in reporting.
	"rider_id" BIGINT NOT NULL,
	-- Driver who accepted.
	"driver_id" BIGINT NOT NULL,
	-- Car actually used, which is what an insurance claim needs.
	"vehicle_id" BIGINT NOT NULL,
	-- Session the trip belonged to. Null once an old session is pruned.
	"session_id" BIGINT,
	-- accepted | arriving | waiting | in_progress | completed | cancelled_by_rider | cancelled_by_driver. Only ever moves forward.
	"status" VARCHAR(32) NOT NULL DEFAULT 'accepted',
	-- State entered: driver accepted. Each of these timestamps is one edge of the state machine, so the sequence is auditable rather than just the latest label.
	"accepted_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- State entered: driver reached the pickup point. Starts the rider wait clock.
	"arrived_at" TIMESTAMPTZ,
	-- State entered: rider in the car. This is when metering begins, not when the driver accepted.
	"started_at" TIMESTAMPTZ,
	-- State entered: trip completed. Null on every cancellation.
	"ended_at" TIMESTAMPTZ,
	-- State entered: cancelled. Mutually exclusive with ended_at.
	"cancelled_at" TIMESTAMPTZ,
	-- Free-text or coded reason, used to decide whether a cancellation fee is fair.
	"cancellation_reason" VARCHAR(120),
	-- Distance actually driven, computed from the pings rather than from the route plan.
	"distance_metres" INTEGER,
	-- Metered seconds from started_at to ended_at, including time stuck in traffic.
	"duration_seconds" INTEGER,
	-- Multiplier snapshotted from the request. Never re-read from surge_multipliers, because the rate in force at booking is the rate owed.
	"surge_multiplier" NUMERIC(4,2) NOT NULL DEFAULT 1,
	-- Sum of the fare components, cached here so a receipt does not aggregate on every open. Null until the trip ends.
	"fare_total_minor" INTEGER,
	-- Currency of fare_total_minor.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Driver share after the platform take. Deliberately not the fare total.
	"driver_earnings_minor" INTEGER,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "trips" IS 'The trip as a state machine where every transition is its own timestamp column. The lifecycle is short and fixed, so a column per state beats an event table: one row answers how long the rider waited, how long the driver waited and how long the ride took.';
COMMENT ON COLUMN "trips"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "trips"."request_id" IS 'Originating request. Unique, so one request can never spawn two trips.';
COMMENT ON COLUMN "trips"."rider_id" IS 'Passenger, copied from the request so the trip stands alone in reporting.';
COMMENT ON COLUMN "trips"."driver_id" IS 'Driver who accepted.';
COMMENT ON COLUMN "trips"."vehicle_id" IS 'Car actually used, which is what an insurance claim needs.';
COMMENT ON COLUMN "trips"."session_id" IS 'Session the trip belonged to. Null once an old session is pruned.';
COMMENT ON COLUMN "trips"."status" IS 'accepted | arriving | waiting | in_progress | completed | cancelled_by_rider | cancelled_by_driver. Only ever moves forward.';
COMMENT ON COLUMN "trips"."accepted_at" IS 'State entered: driver accepted. Each of these timestamps is one edge of the state machine, so the sequence is auditable rather than just the latest label.';
COMMENT ON COLUMN "trips"."arrived_at" IS 'State entered: driver reached the pickup point. Starts the rider wait clock.';
COMMENT ON COLUMN "trips"."started_at" IS 'State entered: rider in the car. This is when metering begins, not when the driver accepted.';
COMMENT ON COLUMN "trips"."ended_at" IS 'State entered: trip completed. Null on every cancellation.';
COMMENT ON COLUMN "trips"."cancelled_at" IS 'State entered: cancelled. Mutually exclusive with ended_at.';
COMMENT ON COLUMN "trips"."cancellation_reason" IS 'Free-text or coded reason, used to decide whether a cancellation fee is fair.';
COMMENT ON COLUMN "trips"."distance_metres" IS 'Distance actually driven, computed from the pings rather than from the route plan.';
COMMENT ON COLUMN "trips"."duration_seconds" IS 'Metered seconds from started_at to ended_at, including time stuck in traffic.';
COMMENT ON COLUMN "trips"."surge_multiplier" IS 'Multiplier snapshotted from the request. Never re-read from surge_multipliers, because the rate in force at booking is the rate owed.';
COMMENT ON COLUMN "trips"."fare_total_minor" IS 'Sum of the fare components, cached here so a receipt does not aggregate on every open. Null until the trip ends.';
COMMENT ON COLUMN "trips"."currency_code" IS 'Currency of fare_total_minor.';
COMMENT ON COLUMN "trips"."driver_earnings_minor" IS 'Driver share after the platform take. Deliberately not the fare total.';

CREATE INDEX "idx_trips_driver_time"
ON "trips" ("driver_id", "accepted_at");
CREATE INDEX "idx_trips_rider_time"
ON "trips" ("rider_id", "accepted_at");
CREATE INDEX "idx_trips_status"
ON "trips" ("status");

CREATE TABLE IF NOT EXISTS "trip_waypoints" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Trip the stop belongs to.
	"trip_id" BIGINT NOT NULL,
	-- Order along the route. 0 is the pickup and the highest value is the final dropoff.
	"sequence" SMALLINT NOT NULL,
	-- pickup | stop | dropoff. A multi-stop ride is simply more rows.
	"kind" VARCHAR(16) NOT NULL,
	-- Planned coordinate of the stop.
	"latitude" NUMERIC(9,6) NOT NULL,
	-- Planned coordinate of the stop.
	"longitude" NUMERIC(9,6) NOT NULL,
	-- Label shown in the receipt, snapshotted at the time.
	"address" VARCHAR(240),
	-- When the car actually reached this stop. Null for stops not yet reached.
	"arrived_at" TIMESTAMPTZ,
	-- When it left. The gap is waiting time, which some tiers bill for.
	"departed_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "trip_waypoints" IS 'Ordered stops, planned and then stamped as they happen. Pickup and dropoff columns on trips would cap every ride at two points and make adding a stop mid-trip a schema change.';
COMMENT ON COLUMN "trip_waypoints"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "trip_waypoints"."trip_id" IS 'Trip the stop belongs to.';
COMMENT ON COLUMN "trip_waypoints"."sequence" IS 'Order along the route. 0 is the pickup and the highest value is the final dropoff.';
COMMENT ON COLUMN "trip_waypoints"."kind" IS 'pickup | stop | dropoff. A multi-stop ride is simply more rows.';
COMMENT ON COLUMN "trip_waypoints"."latitude" IS 'Planned coordinate of the stop.';
COMMENT ON COLUMN "trip_waypoints"."longitude" IS 'Planned coordinate of the stop.';
COMMENT ON COLUMN "trip_waypoints"."address" IS 'Label shown in the receipt, snapshotted at the time.';
COMMENT ON COLUMN "trip_waypoints"."arrived_at" IS 'When the car actually reached this stop. Null for stops not yet reached.';
COMMENT ON COLUMN "trip_waypoints"."departed_at" IS 'When it left. The gap is waiting time, which some tiers bill for.';

CREATE UNIQUE INDEX "uq_waypoints_trip_sequence"
ON "trip_waypoints" ("trip_id", "sequence");

CREATE TABLE IF NOT EXISTS "location_pings" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Driver the device belongs to. Present on every ping, including the ones sent while idle.
	"driver_id" BIGINT NOT NULL,
	-- Trip in progress, null when the driver is online but not on a trip. That null is what separates the dispatch heat map from the billable route.
	"trip_id" BIGINT,
	-- Device clock time of the fix, not server receipt time, because pings arrive out of order after a tunnel.
	"recorded_at" TIMESTAMPTZ NOT NULL,
	-- Reported position.
	"latitude" NUMERIC(9,6) NOT NULL,
	-- Reported position.
	"longitude" NUMERIC(9,6) NOT NULL,
	-- Speed in metres per second, used for traffic estimates and harsh-braking safety signals.
	"speed_mps" NUMERIC(6,2),
	-- Bearing 0-359, used to point the car marker the right way.
	"heading_degrees" SMALLINT,
	-- Reported GPS accuracy. Low-confidence fixes are dropped before distance is computed rather than after.
	"accuracy_metres" SMALLINT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "location_pings" IS 'The append-only breadcrumb trail, written every few seconds and never updated. It is the highest-volume table by a wide margin, which is why it carries no wide columns and is the first candidate for time partitioning and a short retention window.';
COMMENT ON COLUMN "location_pings"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "location_pings"."driver_id" IS 'Driver the device belongs to. Present on every ping, including the ones sent while idle.';
COMMENT ON COLUMN "location_pings"."trip_id" IS 'Trip in progress, null when the driver is online but not on a trip. That null is what separates the dispatch heat map from the billable route.';
COMMENT ON COLUMN "location_pings"."recorded_at" IS 'Device clock time of the fix, not server receipt time, because pings arrive out of order after a tunnel.';
COMMENT ON COLUMN "location_pings"."latitude" IS 'Reported position.';
COMMENT ON COLUMN "location_pings"."longitude" IS 'Reported position.';
COMMENT ON COLUMN "location_pings"."speed_mps" IS 'Speed in metres per second, used for traffic estimates and harsh-braking safety signals.';
COMMENT ON COLUMN "location_pings"."heading_degrees" IS 'Bearing 0-359, used to point the car marker the right way.';
COMMENT ON COLUMN "location_pings"."accuracy_metres" IS 'Reported GPS accuracy. Low-confidence fixes are dropped before distance is computed rather than after.';

CREATE INDEX "idx_pings_trip_time"
ON "location_pings" ("trip_id", "recorded_at");
CREATE INDEX "idx_pings_driver_time"
ON "location_pings" ("driver_id", "recorded_at");

CREATE TABLE IF NOT EXISTS "fare_components" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Trip being charged.
	"trip_id" BIGINT NOT NULL,
	-- base | distance | time | surge | booking_fee | wait_time | toll | airport_fee | tip | promotion | cancellation_fee.
	"kind" VARCHAR(32) NOT NULL,
	-- Amount in minor units. Negative for promotions and adjustments, which is what keeps the sum honest.
	"amount_minor" INTEGER NOT NULL,
	-- Currency of amount_minor.
	"currency_code" CHAR(3) NOT NULL,
	-- Units the charge was computed over, e.g. 4.812 kilometres or 613 seconds.
	"quantity" NUMERIC(10,3),
	-- Rate per unit at the time. Together with quantity this makes the line reproducible years later.
	"unit_rate_minor" INTEGER,
	-- Tips and some regulatory fees are not taxable, and tax has to be computed per line rather than on the total.
	"taxable" BOOLEAN NOT NULL DEFAULT true,
	-- When the line was written.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "fare_components" IS 'The receipt, one row per line. A rider disputing a price wants to know which part was surge and which was a toll, and a single fare column on trips can never answer that or survive a partial refund.';
COMMENT ON COLUMN "fare_components"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "fare_components"."trip_id" IS 'Trip being charged.';
COMMENT ON COLUMN "fare_components"."kind" IS 'base | distance | time | surge | booking_fee | wait_time | toll | airport_fee | tip | promotion | cancellation_fee.';
COMMENT ON COLUMN "fare_components"."amount_minor" IS 'Amount in minor units. Negative for promotions and adjustments, which is what keeps the sum honest.';
COMMENT ON COLUMN "fare_components"."currency_code" IS 'Currency of amount_minor.';
COMMENT ON COLUMN "fare_components"."quantity" IS 'Units the charge was computed over, e.g. 4.812 kilometres or 613 seconds.';
COMMENT ON COLUMN "fare_components"."unit_rate_minor" IS 'Rate per unit at the time. Together with quantity this makes the line reproducible years later.';
COMMENT ON COLUMN "fare_components"."taxable" IS 'Tips and some regulatory fees are not taxable, and tax has to be computed per line rather than on the total.';
COMMENT ON COLUMN "fare_components"."created_at" IS 'When the line was written.';

CREATE INDEX "idx_fare_components_trip_kind"
ON "fare_components" ("trip_id", "kind");

CREATE TABLE IF NOT EXISTS "ratings" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Trip being rated.
	"trip_id" BIGINT NOT NULL,
	-- rider_to_driver | driver_to_rider. The two directions together are what makes the marketplace two-sided.
	"direction" VARCHAR(16) NOT NULL,
	-- Stars from 1 to 5. Five is the practical default, which is why anything below it is treated as a complaint.
	"score" SMALLINT NOT NULL,
	-- Comma-separated coded reasons, e.g. clean_car,great_route. Coded so they can be counted across languages.
	"tags" VARCHAR(240),
	-- Free text, read by support rather than shown publicly. Ride ratings are aggregate-only in both directions.
	"comment" TEXT,
	-- Submission time. Ratings stay editable for a short window after this.
	"submitted_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "ratings" IS 'At most one rating per direction per trip, enforced by the unique pair. Unlike a marketplace of stays, neither score is ever published verbatim: only the rolling mean on riders and drivers is, which is why the cached averages live on those tables.';
COMMENT ON COLUMN "ratings"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "ratings"."trip_id" IS 'Trip being rated.';
COMMENT ON COLUMN "ratings"."direction" IS 'rider_to_driver | driver_to_rider. The two directions together are what makes the marketplace two-sided.';
COMMENT ON COLUMN "ratings"."score" IS 'Stars from 1 to 5. Five is the practical default, which is why anything below it is treated as a complaint.';
COMMENT ON COLUMN "ratings"."tags" IS 'Comma-separated coded reasons, e.g. clean_car,great_route. Coded so they can be counted across languages.';
COMMENT ON COLUMN "ratings"."comment" IS 'Free text, read by support rather than shown publicly. Ride ratings are aggregate-only in both directions.';
COMMENT ON COLUMN "ratings"."submitted_at" IS 'Submission time. Ratings stay editable for a short window after this.';

CREATE UNIQUE INDEX "uq_ratings_trip_direction"
ON "ratings" ("trip_id", "direction");

